package com.luminor.tavernquest.data.local.database.dao
import androidx.room.*; import com.luminor.tavernquest.data.local.database.entity.QuestCompletionEntity; import kotlinx.coroutines.flow.Flow
@Dao interface QuestCompletionDao{@Insert(onConflict=OnConflictStrategy.ABORT) suspend fun insert(v:QuestCompletionEntity);@Query("SELECT * FROM check_in WHERE id=:id") suspend fun getById(id:String):QuestCompletionEntity?;@Query("SELECT COUNT(*) FROM check_in WHERE dailyContractId=:dailyContractId AND syncStatus!='REJECTED'") suspend fun countOpenForContract(dailyContractId:String):Int;@Query("SELECT * FROM check_in ORDER BY completedAt DESC") fun observeAll():Flow<List<QuestCompletionEntity>>;@Query("SELECT DISTINCT date(completedAt/1000,'unixepoch','localtime') FROM check_in") suspend fun getCompletedDates():List<String>;@Query("SELECT COUNT(*) FROM check_in") suspend fun count():Int;@Query("DELETE FROM check_in") suspend fun deleteAll()}
